var t=document.getElementById("auth-form"),o=document.getElementById("error");t.addEventListener("submit",async r=>{r.preventDefault(),o.hidden=!0;try{let e=await fetch(t.dataset.endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(new FormData(t)))}),n=await e.json().catch(()=>({}));if(!e.ok)throw new Error(n.message??n.error??"No se pudo completar la operaci\xF3n.");location.href=t.dataset.next}catch(e){o.textContent=e.message,o.hidden=!1}});
